                description = "<p>Deze week praten Wout Funnekotter, Jurian Ubachs, Arnoud Wokke en Eric van Ballegoie over het overlijden van Erik Bais, adblockers en YouTube, een slimme ring van AliExpress, Xbox'en van andere fabrikanten en helderdere en grotere tv's.</p> <p>0:00 Intro<br>0:21 Opening<br>1:11 .post<br>13:37 Erik Bais is overleden<br>16:48 Nuances rond YouTube en adblockers<br>32:10 Een slimme ring van Ali: anders dan je verwacht<br>42:36 Een Xbox ingebouwd in je tv?<br>51:39 Tv's worden groter en helderder<br>1:10:19 Sneakpeek</p><p>See <a href=\"https://omnystudio.com/listener\">omnystudio.com/listener</a> for privacy information.</p>",
                audioUrl = "https://traffic.omny.fm/d/clips/33dbd2dc-d464-471d-9feb-abae00330078/ed6f6972-a49d-4979-be1d-abae00cd3a92/679c8090-48fe-42a6-9415-b17f00cf7afd/audio.mp3?utm_source=Podcast&in_playlist=70ce1b8c-8e0d-4029-9f69-abae00cd3a97",
