                title = "PvdA-icoon: ‘Ik ga niet op Timmermans stemmen’",
                description = "Kernenergie lijkt een splijtzwam te worden in de verkiezingscampagne. Waarom is Frans Timmermans zó tegen? In Het Haags Kwartiertje bespreken de politiek verslaggevers van De Telegraaf hoe de bakens aan de linkerkant aan het verschuiven zijn. Sinds woensdagochtend is ook de StemWijzer in de lucht, de eerste gids voor zwevende kiezers. Parlementair journalist Valentijn Bartels was bij de lancering en zag hoe nerveus partijleiders waren om hun eigen proefwerk te maken. En in de rubriek Het Orakel verklapt PvdA-coryfee Lutz Jacobi dat zij niet op Timmermans zal stemmen.<p>See <a href=\"https://omnystudio.com/listener\">omnystudio.com/listener</a> for privacy information.</p>",
                audioUrl = "https://traffic.omny.fm/d/clips/fdd7ab40-270d-4a1e-a257-acd200da1324/a6e37ce6-10f5-43f1-928c-b0a100c71692/ec27e671-8f7d-469a-a563-b0a600e76307/audio.mp3?utm_source=Podcast&in_playlist=0aa42add-53e0-4d3a-abdc-b0a100c7191d",
                duration = "937",
                publishedAt = Instant.parse("2023-10-25T14:03:04Z"),
            ),
            Episode(
                id = "36fd9f8f-65cc-466a-839f-05d1f95a4c80",
                title = "‘Hier hengelt Omtzigt naar PVV-kiezers’",
                description = "Maakt Pieter Omtzigt de verwachtingen waar met zijn verkiezingsprogramma? In Het Haags Kwartiertje bespreken de politiek verslaggevers van De Telegraaf wat hen is opgevallen in de plannen van het Nieuw Sociaal Contract. De financiële onderbouwing ontbreekt, aldus politiek commentator Wouter de Winther. „En dat voor de man van de cijfers.” Ook is het de beurt aan politiek orakel Jan Terlouw om zijn licht te schijnen over de campagne.<p>See <a href=\"https://omnystudio.com/listener\">omnystudio.com/listener</a> for privacy information.</p>",
                audioUrl = "https://traffic.omny.fm/d/clips/fdd7ab40-270d-4a1e-a257-acd200da1324/a6e37ce6-10f5-43f1-928c-b0a100c71692/68d413fc-b1ff-4780-99c2-b0a500e48247/audio.mp3?utm_source=Podcast&in_playlist=0aa42add-53e0-4d3a-abdc-b0a100c7191d",
                duration = "952",
