            Episode(
                id = "42046644-b6bc-4538-9982-c2e1d6e8b8b0",
                title = "S1 E1 - Het verhaal van Gerard Sanderink | Aflevering 1: De dag dat alles veranderde",
                description = "<p>Het eerste seizoen van Achter Gesloten Deuren neemt je mee in het verhaal van de Twentse multimiljonair en ondernemer Gerard Sanderink.</p> <p>In de eerste aflevering maak je kennis met Gerard Sanderink als persoon en zakenman. En je ontmoet zijn ex-vriendin Brigitte van Egten.&nbsp;</p> <p>De uitgebreide shownotes en de reacties vind je op <a href=\"fd.nl/sanderink\">fd.nl/sanderink</a></p> <p>Redactie en productie: Jildou Beiboer, Luc van den Berg, Stijn van Gils, Joris Polman en Paulien Sewuster</p> <p>Muziek: Visionair Ordinair</p><p>See <a href=\"https://omnystudio.com/listener\">omnystudio.com/listener</a> for privacy information.</p>",
                audioUrl = "https://traffic.omny.fm/d/clips/8257a063-6be9-42fa-b892-acd4013b1255/b78de77c-664f-4baa-a146-ae6800769bd8/cb6385d1-2a7d-4c5f-9d36-ae85007d2b72/audio.mp3?utm_source=Podcast&in_playlist=f87f2967-1a80-4fca-b9f6-ae680076e49e",
