        episodes = listOf(
            Episode(
                id = "29c64d24-2dc9-4708-b6d8-c61e0bd94633",
                title = "#5 - Everything Bitcoin met Merijn Nijhuis",
                description = "<p>PATREON 👉 <a href=\"https://www.patreon.com/bozegeestenpodcast\">https://www.patreon.com/bozegeestenpodcast</a></p>\n<p><br></p>\n<p>'Mensen zijn gevoelige en emotionele wezens,' zegt Merijn Nijhuis over de nieuwe bitcoin- en blockchaintechnologie, 'zeker als het op geld aankomt. Daarom moet je ervoor zorgen dat het systeem goed werkt, en dat systeem niet vervuilen met allerlei ideologische experimenten, zoals de centrale banken-alchemie, de alchemie van de financiële wereld.'</p>\n<p><br></p>\n<p>In deze aflevering ga ik in gesprek met de getalenteerde jonge investeerder Merijn Nijhuis.Nijhuis ziet de huidige ontwikkelingen in de cryptowereld als een logische reactie op de radicale monetaire experimenten van centrale banken en overheden.&nbsp;</p>\n<p><br></p>\n<p>'Die monetaire storm, zo zie ik het een beetje, die nu heerst en die de komende jaren ook nog zal heersen, daarin gebeuren interessante dingen, en zie je interessante dingen verschuiven, en vanuit dat opzicht kun je een conceptueel wereldbeeld ontwikkelen waarin het redelijkerwijs logisch is dat je een deel van je vermogen in bijvoorbeeld bitcoin hebt.'</p>\n<p><br></p>\n<p>***</p>\n<p><br></p>\n<p>👉 Steun het kanaal via Patreon:<br>\n<a href=\"https://www.patreon.com/bozegeestenpodcast\">https://www.patreon.com/bozegeestenpodcast</a></p>\n<p><br></p>\n<p>👉 Steun het kanaal via Petje af: <br>\n<a href=\"https://petje.af/bozegeestenpodcast\">https://petje.af/bozegeestenpodcast&nbsp;</a></p>\n<p><br></p>\n<p>👉 Volg het debat op Instagram: <br>\n<a href=\"https://www.instagram.com/michiellieuwma/\">https://www.instagram.com/michiellieuwma/</a></p>\n<p><br></p>\n<p>👉 SUBSCRIBE op het YouTube-kanaal en krijg notificaties van nieuwste afl: <a href=\"https://www.youtube.com/channel/UC7NxD1gugqog0fzMOAflOKA?sub_confirmation=1\">https://www.youtube.com/channel/UC7NxD1gugqog0fzMOAflOKA?sub_confirmation=1</a></p>\n<p><br></p>\n<p>***</p>\n<p><br></p>\n<p>Merijn Nijhuis&nbsp;</p>\n<p><br></p>\n<p>Instagram: <a href=\"https://instagram.com/merijnnij?utm_medium=copy_link\">https://instagram.com/merijnnij?utm_medium=copy_link</a><br>\nTwitter: <a href=\"https://mobile.twitter.com/Merijnnij\">https://mobile.twitter.com/Merijnnij</a></p>\n<p><br></p>\n<p>***</p>\n",
                audioUrl = "https://anchor.fm/s/5b473960/podcast/play/34470933/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2021-4-31%2F78d437e4-ccd4-65dc-4553-e50f4e2812c3.mp3",
