    "3757367f-f15b-4765-ad87-a7be09969fe0" to Podcast(
        id = "3757367f-f15b-4765-ad87-a7be09969fe0",
        url = "https://feeds.soundcloud.com/users/soundcloud:users:1086140401/sounds.rss",
        name = "Wynia's Week",
        image = "https://i1.sndcdn.com/avatars-nwCoapiDfRkZeUSX-UkuUjw-original.jpg",
        createdAt = Instant.parse("2026-04-14T22:14:28.207787Z"),
        episodes = listOf(
            Episode(
                id = "d32db172-0143-4564-866b-64d1c0976ef4",
                title = "Wierd Duk: ‘Het kan ook boemerang worden voor Poetin’",
                description = "WIERD DUK, nu verslaggever bij De Telegraaf, was eerder correspondent in Moskou. Hij schreef een biografie van Vladimir Poetin. Duk waarschuwde al voor de opgebouwde wrok in het Kremlin toen dat in Nederland nog een onderschat thema was.\n\nSYP WYNIA spreekt met Wierd over de oorlog in Oekraïne. Waarom Poetins oorlog geen volstrekte verrassing mag heten. Over de denkbare scenario’s en de gevolgen.\n\nWierd Duk denkt dat het Russische leger ondanks gemodder op het slagveld door zal gaan tot Poetins doelen zijn gehaald. Maar hij sluit niet helemaal uit dat Poetins oorlog zich ook nog tegen hem kan keren. Dat zal geen zegen zijn voor het westen, mocht het zover komen, denkt Wierd Duk. Een chaotisch Rusland is nog erger dan een Rusland met Poetin.\n\nKijk en luister!",
                audioUrl = "https://feeds.soundcloud.com/stream/1228564831-user-309107318-wierd-duk-het-kan-ook-boemerang-worden-voor-poetin.mp3",
                duration = "00:55:32",
                publishedAt = Instant.parse("2022-03-08T13:48:10Z"),
            ),
            Episode(
                id = "9b516fa3-7956-478e-9891-0ea0b661dc19",
                title = "Mark Koster - Wie Heeft De Macht Op Het Mediapark",
                description = "MARK KOSTER is een van de weinige mediajournalisten die ook werkelijk over de macht in de media publiceert. Hij schreef al een boek over de machtige mediafamilie De Mol en is nu bezig met een boek over de macht bij de Publieke Omroep. Dat werd hem niet in dank afgenomen: hij raakte zijn radiorubriek over de media kwijt.\n\nDe Mol, RTL\nSYP WYNIA praat met Mark Koster over de machtsconcentratie op het Hilversumse Mediapark, waar de commerciële omroepen (RTL, SBS) zitten en waar ook het kantoor van Talpa (John de Mol) staat. Maar daar zit ook de NPO, de publieke omroep, die van belastinggeld wordt betaald. RTL staat op het punt om SBS over te nemen. Dan zijn er nog maar twee tv-blokken over: RTL en NPO. Is dat niet teveel machtsconcentratie in Hilversum?\n\nHet Haags-Hilversumse huwelijk\nEn hoe zit het met de lijntjes tussen het Haagse Binnenhof en het Hilversumse Mediapark? De publieke omroep wordt immers betaald met geld dat door de Haagse politiek wordt verdeeld? Willen de regeringspartijen daar ook iets voor terug? En als de klassieke regeerpartijen ineenstorten, hoe gaat het dan met hun bevriende omroepen in Hilversum? Is de Hilversumse journalistiek wel kritisch op zichzelf?\n\nIn 55 minuten bijgepraat\nMark Koster neemt geen blad voor de mond over de Macht op het Mediapark en over het wel heel warme Haags-Hilversumse huwelijk. In 55 minuten bent u helemaal bijgepraat.",
                audioUrl = "https://feeds.soundcloud.com/stream/1217445808-user-309107318-mark-koster-wie-heeft-de-macht-op-het-mediapark.mp3",
                duration = "00:55:35",
                publishedAt = Instant.parse("2022-02-17T12:14:19Z"),
            ),
            Episode(
                id = "b848806b-848b-42ef-9979-1bbcf46cf308",
                title = "Bauke Geersing - ‘Verzet Tegen ‘woke’ - Historie Over Nederlands - Indië’",
                description = "Historici, militairen en Indische Nederlanders nemen geen genoegen met het beeld van de geschiedenis dat opgeroepen wordt in een reeks boeken over de ‘Dekolonisatie’ van Nederlands-Indië die binnenkort verschijnt. Onder de hoede van drie instituten onder leiding van het NIOD (‘Oorlogsdocumentatie’) verschijnen er in februari twaalf boeken over de gewelddadige periode 1945-1950 in toenmalig Nederlands-Indië. Dat ‘Dekolonisatie’-project werd op voorstel van de toenmalige PvdA-minister Bert Koenders gesteund met een miljoenensubsidie.\n\n‘Geen geschiedschrijving, maar propaganda’\nSYP WYNIA spreekt in deze video met BAUKE GEERSING van de Stichting Aurora, die zich opwerpt als tolk van het verzet tegen de aanpak van de samenwerkende instituten. Volgens Geersing gebruiken de drie instituten de overheidssubsidie niet om de historische feiten recht te doen, maar om propaganda te bedrijven. Hij gaat daarbij af op alle voorpublicaties van het project en uitlatingen van auteurs en leidinggevenden.\n\n‘Woke-geschiedsschrijving’\nVolgens Geersing – aanvankelijk beroepsmilitair, vervolgens jurist en een van de topmensen van de publieke omroep – bedrijft de groep historici rond het NIOD geschiedschrijving in de geest van de omstreden Amerikaanse ‘critical race theory’ – ook wel als ‘woke’ betiteld – waarbij blanken steevast en uitsluitend als daders en niet-blanken al even voorspelbaar uitsluitend als slachtoffers worden voorgesteld. In het ‘Dekolonisatie’-project zou daar doelbewust sprake van zijn. De werkelijkheid ten tijde van de dekolonisatie van Nederlands-Indië is volgens Geersing c.s. veel genuanceerder (ook veel geweld aan Indonesische kant, bijvoorbeeld). \n\n‘Legeronderdelen tekenen bezwaar aan’\nVolgens Geersing zijn Nederlandse krijgsmachtonderdelen, veteranenorganisaties en organisaties van Indische Nederlanders van plan om verzet aan te tekenen. Zelf pleit Geersing er voor, dat het kabinet-Rutte4 geen genoegen neemt met de uitkomsten van het ‘Dekolonisatie’-project, ook omdat de drie instituten zich niet aan de opdracht van het kabinet Rutte2 zouden hebben gehouden. Geersing: ‘Dit kan nooit het laatste woord zijn. Het is hooguit een tussenstap’.",
                audioUrl = "https://feeds.soundcloud.com/stream/1216266211-user-309107318-bauke-geersing-verzet-tegen-woke-historie-over-nederlands-indie.mp3",
                duration = "00:47:33",
                publishedAt = Instant.parse("2022-02-15T13:11:56Z"),
            ),
            Episode(
                id = "3a1d911d-92bc-4239-98e7-cdfac3b84b5a",
                title = "Kabinet - Rutte Is Verslaafd Geraakt Aan Corona - Maatregelen",
                description = "Twee jaar geleden kwam het Coronavirus Nederland binnen. Eerst was er een overmaat aan zelfvertrouwen aan het Binnenhof. ‘Nederland was goed voorbereid’, heette het. Vervolgens deed Nederland aan een ‘intelligente lockdown’ – wat suggereerde dat andere landen nog wel iets van de slimme Nederlandse aanpak konden leren.\n\nEn nu?\nPIM VAN GALEN en SYP WYNIA analyseren twee jaar Coronabeleid. Het zijn jaren van hollen en stilstaan, van rare paradoxen en van een tendens naar harder ingrijpen dan elders. \nHet heeft er alle schijn van dat het kabinet-Rutte en zijn medische adviseurs maar moeilijk afscheid kunnen nemen van verregaande, in wezen autoritaire ingrepen in de samenleving. \nSyp Wynia: ‘Het heeft er alle schijn van dat het kabinet en de Corona-specialisten verslaafd zijn geraakt aan Corona. De pandemie verschafte hen dan ook een ongekende macht. Dat is wat iedere bureaucraat graag wil.’",
                audioUrl = "https://feeds.soundcloud.com/stream/1216265326-user-309107318-kabinet-rutte-is-verslaafd-geraakt-aan-corona-maatregelen.mp3",
                duration = "00:32:16",
                publishedAt = Instant.parse("2022-02-15T13:09:53Z"),
            ),
            Episode(
                id = "c51dabed-d17a-4410-9905-3c1211f76c30",
                title = "Hoe Politiek Wanbeleid De Schilderswijk Vernielde",
                description = "Onlangs verscheen het boek ‘Het verdriet van de Schilderwijk’ waarin auteur Maaike van Charante verslag doet van de tragische teloorgang van Nederlands bekendste – en wellicht beruchtste – volkswijk tijdens de periode 1960-1980. In een openhartig interview met Andy Arnts vertelt zij welke oorzaken er aan de verloedering van ‘haar’ Schilderswijk ten grondslag lagen en waar deze uiteindelijk toe geleid hebben. Hoe de eens zo gemoedelijke volkswijk door bestuurlijke laksheid, minachting voor de oorspronkelijke bewoners en middenstand en de enorme instroom van migranten volstrekt onleefbaar werd.",
                audioUrl = "https://feeds.soundcloud.com/stream/1216263130-user-309107318-hoe-politiek-wanbeleid-de-schilderswijk-vernielde.mp3",
                duration = "00:26:35",
                publishedAt = Instant.parse("2022-02-15T13:04:44Z"),
            ),
        )
