        name = "Victor Duidt TV",
        image = "https://www.omnycontent.com/d/playlist/61ee9ca4-a1b2-4660-9651-b2b70035edf5/7a0fa413-eff8-429e-846d-b2f100f2b38e/a5100176-262d-49c6-a8f1-b2f100f2b411/image.jpg?t=1751732186&size=Large",
